function zeroTrustMiddleware(requiredPermission) {
  return async (req, res, next) => {
    const token = req.headers['authorization']?.replace('Bearer ', '');
    if (!token) {
      return res.status(401).json({ error: 'missing token' });
    }

    // Verify the token itself: signature, expiry, issuer.
    // Short lived on purpose, usually minutes, never weeks.
    const identity = await verifyShortLivedToken(token);
    if (!identity) {
      return res.status(401).json({ error: 'invalid or expired token' });
    }

    // Note: we never check req.ip or whether this came over the VPN.
    // Network origin grants zero trust by itself.

    const allowed = await checkPermission(identity, requiredPermission);
    if (!allowed) {
      return res.status(403).json({ error: 'not authorized for this action' });
    }

    req.identity = identity;
    next();
  };
}

// Usage on the refund route:
app.post('/admin/refunds', zeroTrustMiddleware('refunds:issue'), issueRefund);
app.get('/admin/tickets', zeroTrustMiddleware('tickets:view'), listTickets);

